import{_ as t,o as e,c as o,ai as l}from"./chunks/framework.scx6l_IK.js";const q=JSON.parse('{"title":"小周天","description":"","frontmatter":{},"headers":[],"relativePath":"50-概念资料/dict-小周天.md","filePath":"50-概念资料/dict-小周天.md","lastUpdated":1778155802000}'),i={name:"50-概念资料/dict-小周天.md"};function r(c,a,d,u,h,n){return e(),o("div",null,[...a[0]||(a[0]=[l('<h1 id="小周天" tabindex="-1">小周天 <a class="header-anchor" href="#小周天" aria-label="Permalink to &quot;小周天&quot;">​</a></h1><blockquote><p>传统：丹道</p></blockquote><h2 id="定义" tabindex="-1">定义 <a class="header-anchor" href="#定义" aria-label="Permalink to &quot;定义&quot;">​</a></h2><p>小周天是道家丹道修炼中的一个阶段——真气打通任督二脉，在体内形成一个循环，感觉如&quot;运转&quot;。</p><h2 id="了空居士原话" tabindex="-1">了空居士原话 <a class="header-anchor" href="#了空居士原话" aria-label="Permalink to &quot;了空居士原话&quot;">​</a></h2><blockquote><p>&quot;小周天就是任督二脉通了，气沿着这条路线自然运转。不需要用意念去引导，是自然发生的。&quot;</p></blockquote><blockquote><p>&quot;但安神息，不运火而火自运——只要你心平气和，火候就恰到好处，自然运行。&quot;</p></blockquote><blockquote><p>&quot;不可用意念去引气。引气容易出偏差，气满自通。&quot;</p></blockquote><h2 id="了空居士的独特观点" tabindex="-1">了空居士的独特观点 <a class="header-anchor" href="#了空居士的独特观点" aria-label="Permalink to &quot;了空居士的独特观点&quot;">​</a></h2><p><strong>最关键的观点</strong>：不要追求、不要用意念引导。了空居士反复强调小周天是<strong>自然形成</strong>的，不是&quot;练出来&quot;的。</p><h2 id="相关概念" tabindex="-1">相关概念 <a class="header-anchor" href="#相关概念" aria-label="Permalink to &quot;相关概念&quot;">​</a></h2><ul><li><a href="/50-概念资料/dict-大周天">大周天</a> — 小周天之后的进阶</li><li><a href="/50-概念资料/dict-任脉">任脉</a> — 小周天运行的路径之一</li><li><a href="/50-概念资料/dict-督脉">督脉</a> — 小周天运行的路径之二</li><li><a href="/50-概念资料/dict-丹田">丹田</a> — 小周天的能量核心</li></ul><h2 id="相关模型" tabindex="-1">相关模型 <a class="header-anchor" href="#相关模型" aria-label="Permalink to &quot;相关模型&quot;">​</a></h2><ul><li><a href="/10-核心模型/model-性命双修">性命双修</a> — 命功修炼涉及的核心概念</li></ul><h2 id="修行实践" tabindex="-1">修行实践 <a class="header-anchor" href="#修行实践" aria-label="Permalink to &quot;修行实践&quot;">​</a></h2><ul><li>不求通周天，只求心平气和</li><li>功夫到了自然通，不到不要硬来</li><li>感觉对了就对了，感觉不到也不着急</li></ul>',16)])])}const _=t(i,[["render",r]]);export{q as __pageData,_ as default};
